package parser

import ("strconv"; "testing")

func ParseInt(s string)(int,error){return strconv.Atoi(s)}

func FuzzParseInt(f *testing.F){f.Add("42");f.Add("not-a-number");f.Fuzz(func(t *testing.T,input string){_,err:=ParseInt(input);if err!=nil{return}})}

// Run with: go test -fuzz=FuzzParseInt
